import * as T from './three.module.js';
export const ICE_BASIC={left:{name:'얼음탄',damage:7,cost:4,cooldown:.8,windup:.18,lock:.3,range:7,speed:13},right:{name:'얼음안개',damage:2,cost:7,cooldown:2.4,windup:0,lock:1.2,range:2.6,life:1.2,interval:.2}};
export class IceBasic{
 constructor(api){this.a=api;this.effects=[];}
 cast(owner,dir,hand){const spec=ICE_BASIC[hand],side=hand==='left'?-1:1;owner.iceCastLock=Math.max(owner.iceCastLock||0,spec.lock);const bone=owner.g?.userData.puppet?.lastPositions?.[hand==='left'?'LeftHand':'RightHand'];let origin=bone?.clone()||new T.Vector3(owner.x+dir.z*.32*side,1.1,owner.z-dir.x*.32*side);if(!this.a.clearPath(owner,origin))origin.set(owner.x,1.1,owner.z);const ring=new T.Group();for(const [radius,tube,opacity,color] of [[.28,.018,1,0xd7f6ff],[.28,.043,.65,0x159dff],[.28,.075,.20,0x167fff],[.37,.009,.8,0x5dcaff]]){const m=new T.Mesh(new T.TorusGeometry(radius,tube,8,48),new T.MeshBasicMaterial({color,transparent:true,opacity,depthWrite:false,blending:T.AdditiveBlending}));m.userData.alpha=opacity;ring.add(m);}for(let j=0;j<8;j++){const m=new T.Mesh(new T.BoxGeometry(.018,.07,.012),new T.MeshBasicMaterial({color:0x9ce8ff,transparent:true,opacity:1,depthWrite:false,blending:T.AdditiveBlending}));const a=j*Math.PI/4;m.position.set(Math.cos(a)*.33,Math.sin(a)*.33,0);m.rotation.z=a-Math.PI/2;m.userData.alpha=1;ring.add(m);}ring.add(new T.PointLight(0x168bff,1.8,2));ring.position.copy(origin);ring.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),new T.Vector3(dir.x,0,dir.z));this.a.scene.add(ring);const life=hand==='right'?spec.life:.48;this.effects.push({type:'iceHandRing',mesh:ring,owner,hand,dir:dir.clone(),life,max:life});
 if(spec.windup){const mesh=new T.Group();mesh.position.copy(origin);this.effects.push({type:'iceWindup',mesh,owner,hand,dir:dir.clone(),life:spec.windup});}else this.emit(owner,dir,hand,origin);
 }
 emit(owner,dir,hand,origin){const spec=ICE_BASIC[hand];
 if(hand==='left'){const mesh=new T.Mesh(new T.OctahedronGeometry(.16,0),new T.MeshStandardMaterial({color:0x8edcff,emissive:0x1874bb,emissiveIntensity:.7,roughness:.2}));mesh.position.copy(origin);mesh.scale.set(.7,.7,2);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),dir);this.a.scene.add(mesh);this.effects.push({type:'shot',mesh,owner,dir:dir.clone(),speed:spec.speed,life:spec.range/spec.speed,damage:spec.damage});}
 else{const mesh=new T.Group();for(let j=0;j<64;j++){const shard=j>=40,puff=new T.Mesh(shard?new T.OctahedronGeometry(.055,0):new T.SphereGeometry(1,8,6),new T.MeshBasicMaterial({color:shard?0xd9f7ff:j%3?0x6dcaff:0xe0f8ff,transparent:true,opacity:0,depthWrite:false,blending:shard?T.AdditiveBlending:T.NormalBlending}));puff.userData={shard,seed:j*.618,angle:Math.sin(j*2.4)*.69};mesh.add(puff);}const halo=new T.Mesh(new T.TorusGeometry(.32,.025,5,32),new T.MeshBasicMaterial({color:0x62caff,transparent:true,opacity:.8,depthWrite:false,blending:T.AdditiveBlending}));halo.position.set(0,1.05,.1);halo.userData.halo=true;mesh.add(halo);mesh.position.set(origin.x,0,origin.z);mesh.rotation.y=Math.atan2(dir.x,dir.z);this.a.scene.add(mesh);this.effects.push({type:'iceMist',mesh,owner,dir:dir.clone(),point:{x:origin.x,z:origin.z},life:spec.life,max:spec.life,tick:0});}}
 update(dt){for(let i=this.effects.length-1;i>=0;i--){const e=this.effects[i];e.life-=dt;let done=e.life<=0;
 if(e.type==='iceHandRing'){const bone=e.owner.g?.userData.puppet?.lastPositions?.[e.hand==='left'?'LeftHand':'RightHand'];if(bone)e.mesh.position.copy(bone);const fade=Math.min(1,Math.max(0,e.life/.15));e.mesh.traverse(m=>{if(m.material)m.material.opacity=m.userData.alpha*fade;if(m.isPointLight)m.intensity=1.8*fade;});e.mesh.scale.setScalar(1+(1-e.life/e.max)*.3);}
 if(e.type==='iceWindup'&&done&&e.owner.hp>0)this.emit(e.owner,e.dir,e.hand,e.mesh.position.clone());
 if(e.type==='shot'&&!done){const steps=Math.max(1,Math.ceil(e.speed*dt/.08));for(let j=0;j<steps&&!done;j++){const before=e.mesh.position.clone(),next=before.clone().addScaledVector(e.dir,e.speed*dt/steps);if(this.a.collides(next.x,next.z,.12)||!this.a.clearPath(before,next)){done=true;break;}e.mesh.position.copy(next);const target=this.a.targets(e.owner).find(t=>Math.hypot(t.x-next.x,t.z-next.z)<.55);if(target){if(this.a.hit(target,e.damage,e.dir,0,e.owner))target.slow=Math.max(target.slow||0,1.2);done=true;}}}
 if(e.type==='iceMist'){e.tick-=dt;const age=e.max-e.life,fade=Math.min(1,e.life/.3);for(const p of e.mesh.children){const u=p.userData;if(u.halo){p.material.opacity=.8*fade;p.rotation.z=age*2;continue;}const phase=(age*(u.shard?1.8:1.15)+u.seed)%1,travel=.15+phase*2.3,width=.08+phase*.35;p.position.set(Math.sin(u.angle)*travel+Math.sin(age*8+u.seed)*width*.2,1.05-phase*.45+Math.sin(u.seed*5+age*4)*.13,Math.cos(u.angle)*travel);if(u.shard){p.scale.set(.6,1.8+phase, .6);p.rotation.set(age*3+u.seed,age*2,u.seed);p.material.opacity=Math.sin(phase*Math.PI)*fade*.95;}else{const size=.12+phase*.4;p.scale.set(size*(1+phase*.45),size*.7,size);p.material.opacity=Math.sin(phase*Math.PI)*fade*.33;}}if(!done&&e.tick<=0){e.tick+=.2;for(const t of this.a.targets(e.owner)){const dx=t.x-e.point.x,dz=t.z-e.point.z,d=Math.hypot(dx,dz);if(d>2.6||d>.01&&(dx*e.dir.x+dz*e.dir.z)/d<.65||!this.a.clearPath(e.point,t))continue;if(this.a.hit(t,2,e.dir,0,e.owner))t.slow=Math.max(t.slow||0,.8);}}}
 if(done){this.a.remove(e.mesh);this.effects.splice(i,1);}}}
 clear(){for(const e of this.effects)this.a.remove(e.mesh);this.effects=[];}
}
